tool_input.command:
cd D:\repository\门户\zhi2-web-admin; $f='src\views\property\marketMonitor\components\TradePanel.vue'; $lines=Get-Content $f; # left side lines ~37-125, right ~128-216. Extract class="..." attrs and normalize colors
function Norm($s){ $s = $s -replace 'blue|emerald|teal|slate-900|resale|commercial|City|Urban|d\.commercial|d\.resale','X'; return $s }
echo '=== LEFT classes ==='; $lines[36..124] | Select-String -Pattern 'class="' | ForEach-Object { ($_.Matches | ForEach-Object {$_.Value}) } | Out-Null
$left = $lines[36..124] -join "`n"; $right = $lines[127..215] -join "`n"
$lc = [regex]::Matches($left,'class="([^"]*)"') | ForEach-Object { ($_.Groups[1].Value -replace 'blue-\d+','C' -replace 'emerald-\d+','C' -replace 'teal-\d+','C') }
$rc = [regex]::Matches($right,'class="([^"]*)"') | ForEach-Object { ($_.Groups[1].Value -replace 'blue-\d+','C' -replace 'emerald-\d+','C' -replace 'teal-\d+','C') }
Write-Output "left class count=$($lc.Count) right=$($rc.Count)"
for($i=0;$i -lt [Math]::Max($lc.Count,$rc.Count);$i++){ $l=if($i -lt $lc.Count){$lc[$i]}else{'<none>'}; $r=if($i -lt $rc.Count){$rc[$i]}else{'<none>'}; if($l -ne $r){ Write-Output "DIFF[$i]`n  L: $l`n  R: $r" } }
